window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-24101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριθίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3316 na letra κ · nº geral 24101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grãozinho de cevada. 〈κριθή〉</p></section></article>\n<article id=\"entry-dgp-24102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3317 na letra κ · nº geral 24102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alimentar com cevada. 〈κριθή〉</p></section></article>\n<article id=\"entry-dgp-24103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίθινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3318 na letra κ · nº geral 24103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito ou preparado com cevada. 〈κριθή〉</p></section></article>\n<article id=\"entry-dgp-24104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριθολόγος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3319 na letra κ · nº geral 24104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">critólogo, magistrado encarregado de preparar a cevada para os sacrifícios. 〈κριθή, λέγω〉</p></section></article>\n<article id=\"entry-dgp-24105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριθοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3320 na letra κ · nº geral 24105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que traz ou produz cevada. 〈κριθή, φέρω〉</p></section></article>\n<article id=\"entry-dgp-24106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίκε</h1><div class=\"entry-meta\"><span>DGP · ordem 3321 na letra κ · nº geral 24106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 poét. de κρίζω.</p></section></article>\n<article id=\"entry-dgp-24107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρικοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3322 na letra κ · nº geral 24107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">em forma de círculo. 〈κρίκος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-24108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3323 na letra κ · nº geral 24108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 argola fixada no jugo para atá-lo ao carro 2 anel ou ilhó de vela de navio ou de cortina 3 anel, adorno 4 colar 5 elo de corrente 6 corrente.</p></section></article>\n<article id=\"entry-dgp-24109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρῖμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3324 na letra κ · nº geral 24109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 objeto de contestação; contestação; querela 2 julgamento; decisão judiciária; veredicto 3 decisão; julgamento 4 bíbl. condenação; sentença; punição 5 bíbl. prescrição 6 bíbl. ação de julgar 7 bíbl. direito; justiça. 〈κρίνω〉</p></section></article>\n<article id=\"entry-dgp-24110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρινθείς</h1><div class=\"entry-meta\"><span>DGP · ordem 3325 na letra κ · nº geral 24110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. pas. poét. de κρίνω.</p></section></article>\n<article id=\"entry-dgp-24111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίνον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3326 na letra κ · nº geral 24111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lírio 2 espécie de dança coral 3 espécie de pão.</p></section></article>\n<article id=\"entry-dgp-24112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3327 na letra κ · nº geral 24112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κρινῶ, aor. ἔκρινα, perf. κέκρικα; méd. fut. κρι­νοῦμαι, aor. ἐκρινάμην, perf. κέκριμαι; pas. aor. ἐκρίθην, perf. κέκριμαι) ativa 1 separar; distinguir 2 escolher; selecionar algo ou alguém, ac., dentre, gen. ou ἐκ e gen. ou ἐν e dat.; preferir algo, ac., a, πρό ou πρός e gen. 3 Jur. ser o juiz de (disputas ou competições); emitir ou pronunciar uma sentença sobre, ac.; resolver uma causa ou processo; decidir; dirimir; julgar 4 perseguir em justiça; entrar com demanda; acusar alguém, ac., de, gen. ou περί e gen. 5 explicar; interpretar 6 decidir; resolver 7 decidir com vitória; vencer 8 julgar; estimar; apreciar algo, or. inf. 9 atribuir mediante sentença; adjudicar algo, ac., a alguém, dat. 10 trag., interrogar; questionar média 11 separar; escolher; selecionar algo ou alguém, ac., dentre, gen. ou ἐκ e gen. ou ἐν e dat.; preferir algo, ac., a, πρό ou πρός e gen. 12 decidir; julgar uma contestação para si 13 explicar; interpretar 1 κρῖν’ ἄνδρας κατὰ φῦλα hom. separa os guerreiros por tribos, κρ. τούς τε ἀγαθοὺς καὶ τοὺς κακούς xen. separar os bons e os maus, κ. τὸ ἀληθές τε καὶ μή plat. distinguir o que é e o que não é verdadeiro 2 ἐν δ’ ἐρέταις ἔκρινεν ἐείκοσιν hom. dentre eles, escolheu vinte remeiros, κ. ἀστῶν τὰ βέλτατα ésql. escolher dentre os cidadãos os melhores, κρίνω δ’ ἄφθονον ὄλβον ésql. prefiro uma felicidade isenta de inveja, κρ. τὸν Ἀπόλλω καὶ τὰ τοῦ Ἀπόλλωνος ὄργανα πρὸ Μαρσύου τε καὶ τῶν ἐκείνου ὀργάνων plat. preferir Apolo e os instrumentos dele a Mársias e seus instrumentos 3 κρ. νείκεα πολλά hom. dirimir muitas discórdias, κρινεῖ δὲ δή τις ταῦτα; ar. e quem vai ser o juiz desse concurso?, δίκας κρ. her. julgar, κρῖνε δ’εὐθείαν δίκην plut. pronuncia a reta sentença um processo, κρ. τὰς θεάς eur. julgar as deusas, κρ. θανάτου xen. pronunciar sentença de morte, ὁ κρίνων o acusador ou o juiz, ὁ κρινόμενος o acusado 4 κρ. θανάτου xen. julgar por morte, κρ. προδοσίας lic. ou περὶ προδοσίας isócr. acusar [alguém] de traição 5 κρ. ἐνύπνιον her. interpretar um sonho 6 οὐ γὰρ ἔκρινά τι εἰδέναι ἐν ὑμῖν εἰ μὴ Ἰησοῦν Χριστόν n.t. pois decidi nada saber entre vós que não seja Jesus Cristo 7 τὴν μάχην Ἀννίβας ἔκρινε pol. Aníbal venceu a batalha 8 κρ. μέγιστον ἀγαθὸν εἶναι πλοῦτον plat. julgar que a riqueza é um bem enorme, κρίνω σε νικᾶν ésql. julgo que tu és o vencedor, i.e., que tens razão, πρὸς ἐμαυτὸν κρίνων dem. julgando por mim mesmo, πρὸς ἀργύριον τὴν εὐδαιμονίαν κρ. isócr. julgar pelo dinheiro a felicidade 9 κρίνειν κράτος ἀριστείας τινί sóf. adjudicar a alguém, por sua excelência, o direito de posse [das armas] 10 κύκλῳ γὰρ αὐτὸν Μηλιεὺς ἅπας λεὼς κρίνει παραστάς sóf. todo o povo de Mális, postado em volta dele [Héracles], interroga-o, μὴ κρῖνε, μὴ’ ξέταζε sóf. não perguntes, não investigues 11 ἀρίστους κρινάμενος κατὰ λαὸν Ἀχαιικόν hom. tendo escolhido os melhores dentre o povo aqueu, σὺ δ’ εὖ κρίνασθαι ἑταίρους τρεῖς hom. e tu separa três companheiros 12 κρινώμεθ’ Ἄρηϊ hom. decidamos sua questão por meio de combate, οὐ κρινοῦμαι τῶνδέ σοι τὰ πλείονα eur. não mais que isso discutirei contigo, δίκῃ περί τινος κρίνεσθαι tuc. decidir no tribunal uma questão a respeito de algo 13 ὁ γέρων ἐκρίνατ’ ὀνείρους hom. o velho explicou os sonhos.</p></section></article>\n<article id=\"entry-dgp-24113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριοπρόσωπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3328 na letra κ · nº geral 24113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem cara de carneiro. 〈κριός, πρόσωπον〉</p></section></article>\n<article id=\"entry-dgp-24114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριός, οῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3329 na letra κ · nº geral 24114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 carneiro 2 Astron. Áries; Carneiro, cons­telação 3 Mil. aríete, máquina de guerra 4 cetáceo. 〈κέρας〉</p></section></article>\n<article id=\"entry-dgp-24115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρίσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3330 na letra κ · nº geral 24115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de separar, de distinguir; triagem 2 ação de escolher; escolha; seleção 3 ação de julgar, de decidir; julgamento; decisão: μεγάλων ἀέθλων ἁγνὰν κρίσιν pínd. o sacro julgamento das importantes competições 4 aptidão para decidir; discernimento 5 Jur. julgamento; processo: εἰς κρίσιν ἄγειν plat. conduzir a julgamento, κρίσιν ποιεῖν τινι lís. instaurar processo contra alguém 6 Jur. acusação 7 Jur. condenação 8 solução; êxito; desenlace; resultado: τὴν κρίσιν ἔχειν tuc. ter solução, resolver-se 9 disputa; luta; contestação 10 Medic. crise; fase crítica de uma doença 11 explicação; interpretação de sonho, de prodígio.</p></section></article>\n<article id=\"entry-dgp-24116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρίσπος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3331 na letra κ · nº geral 24116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Crispo, n. de h. [lat.]</p></section></article>\n<article id=\"entry-dgp-24117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 3332 na letra κ · nº geral 24117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de κρίνω.</p></section></article>\n<article id=\"entry-dgp-24118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3333 na letra κ · nº geral 24118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 faculdade de julgar 2 norma para discernir o verdadeiro do falso; critério 3 Jur. corte de justiça; tribunal. 〈κρίνω〉</p></section></article>\n<article id=\"entry-dgp-24119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3334 na letra κ · nº geral 24119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 juiz; árbitro 2 juiz de concurso, de luta 3 rar. juiz de tribunal 4 intérprete. 〈κρίνω〉</p></section></article>\n<article id=\"entry-dgp-24120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κριτίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3335 na letra κ · nº geral 24120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Crítias, n. de h.</p></section></article>\n<article id=\"entry-dgp-24121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3336 na letra κ · nº geral 24121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de julgar, de discernir 2 decisivo; crítico (doença) ♦ ὁ κριτικός 3 o crítico; o gramático ♦ ἡ κριτική 4 arte de julgar ♦ τὸ κριτικόν 5 faculdade de discernir, de julgar. 〈κρίνω〉</p></section></article>\n<article id=\"entry-dgp-24122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3337 na letra κ · nº geral 24122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separado; escolhido 2 eleito; seleto; superior. 〈κρίνω〉</p></section></article>\n<article id=\"entry-dgp-24123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρίτων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3338 na letra κ · nº geral 24123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Critão, n. de h.</p></section></article>\n<article id=\"entry-dgp-24124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3339 na letra κ · nº geral 24124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 (cavalo) bater com o casco; galopar 2 fazer ressoar um canto. 〈κρούω〉</p></section></article>\n<article id=\"entry-dgp-24125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κροίσειος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 3340 na letra κ · nº geral 24125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de Creso. 〈Κροῖσος〉</p></section></article>\n<article id=\"entry-dgp-24126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κροῖσος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3341 na letra κ · nº geral 24126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Creso, rei da Lídia.</p></section></article>\n<article id=\"entry-dgp-24127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκάλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3342 na letra κ · nº geral 24127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 beira do mar; praia 2 calhau. 〈κρόκη〉</p></section></article>\n<article id=\"entry-dgp-24128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόκεος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3343 na letra κ · nº geral 24128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da cor do açafrão. 〈κρόκος〉</p></section></article>\n<article id=\"entry-dgp-24129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3344 na letra κ · nº geral 24129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trama de tecido; fio da trama 2 fio 3 floco de lã 4 tecido 5 seixo 6 praia. 〈κρέκω〉</p></section></article>\n<article id=\"entry-dgp-24130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 3345 na letra κ · nº geral 24130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) = κρόκεος.</p></section></article>\n<article id=\"entry-dgp-24131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκόβαπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3346 na letra κ · nº geral 24131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tingido com açafrão; da cor do açafrão. 〈κρόκος, βάπτω〉</p></section></article>\n<article id=\"entry-dgp-24132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκοβαφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3347 na letra κ · nº geral 24132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κροκόβαπτος.</p></section></article>\n<article id=\"entry-dgp-24133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκόδειλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3348 na letra κ · nº geral 24133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 crocodilo 2 o sofisma do crocodilo.</p></section></article>\n<article id=\"entry-dgp-24134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 3349 na letra κ · nº geral 24134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da cor do açafrão. 〈κρόκος〉</p></section></article>\n<article id=\"entry-dgp-24135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκόπεπλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3350 na letra κ · nº geral 24135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de véu da cor do açafrão. 〈κρόκος, πέπλον〉</p></section></article>\n<article id=\"entry-dgp-24136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3351 na letra κ · nº geral 24136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 açafrão, planta, flor ou produto da planta 2 gema do ovo.</p></section></article>\n<article id=\"entry-dgp-24137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκύς, ύδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3352 na letra κ · nº geral 24137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 penugem de tecido 2 tecido de lã. 〈κρέκω〉</p></section></article>\n<article id=\"entry-dgp-24138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3353 na letra κ · nº geral 24138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tingido com açafrão; da cor de açafrão ♦ ὁ κροκωτός 2 túnica de cor de açafrão usada por mulheres e efeminados. 〈κρόκος〉</p></section></article>\n<article id=\"entry-dgp-24139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκωτοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3354 na letra κ · nº geral 24139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que usa túnica cor de açafrão. 〈κροκωτός, φέρω〉</p></section></article>\n<article id=\"entry-dgp-24140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόμμυον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3355 na letra κ · nº geral 24140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cebola 2 pl. mercado de cebola.</p></section></article>\n<article id=\"entry-dgp-24141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόμυον</h1><div class=\"entry-meta\"><span>DGP · ordem 3356 na letra κ · nº geral 24141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = κρόμμυον.</p></section></article>\n<article id=\"entry-dgp-24142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρόνια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 3357 na letra κ · nº geral 24142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Κρόνιος.</p></section></article>\n<article id=\"entry-dgp-24143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρονιάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 3358 na letra κ · nº geral 24143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Saturno, em Roma: Κρονιάδες ἡμέραι as Saturnais. 〈Κρόνος〉</p></section></article>\n<article id=\"entry-dgp-24144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρονίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3359 na letra κ · nº geral 24144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Cronos, epít. de Zeus.</p></section></article>\n<article id=\"entry-dgp-24145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3360 na letra κ · nº geral 24145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do tempo de Cronos; velho; antigo 2 de Saturno, em Roma: ἡ Κρονικὴ ἑορτή a festa de Saturno; as Saturnais. 〈Κρόνος〉</p></section></article>\n<article id=\"entry-dgp-24146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρόνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3361 na letra κ · nº geral 24146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Κρόνιος.</p></section></article>\n<article id=\"entry-dgp-24147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρόνιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3362 na letra κ · nº geral 24147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Cronos; descendente de Cronos 2 próprio de Cronos: μὴν Κρόνιος plut. o mês das festas de Cronos, o mês Hecatombeon em Atenas, Κρονίη ἅλς a.r. mar de Cronos, i.e., mar Adriático ♦ ὁ Κρόνιος 3 filho de Cronos, epít. de Zeus ♦ ἡ Κρονία e τὸ Κρόνιον 4 monte de Cronos, na Élida ♦ τὰ Κρόνια 5 festas de Cronos, em Atenas; as Saturnais, em Roma 6 o tempo de Cronos: Κρονίων ὄζειν ar. exalar cheiro do tempo de Cronos, i.e., ser velho. 〈Κρόνος〉</p></section></article>\n<article id=\"entry-dgp-24148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρόνιων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 3363 na letra κ · nº geral 24148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ονος (ὁ) filho de Cronos, Zeus.</p></section></article>\n<article id=\"entry-dgp-24149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρονόληρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3364 na letra κ · nº geral 24149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">velho tonto. 〈Kρόνος, λῆρος〉</p></section></article>\n<article id=\"entry-dgp-24150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρόνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3365 na letra κ · nº geral 24150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cronos; em Roma, Saturno, Titã, filho de Urano e pai de Zeus. 〈κραίνω〉</p></section></article>\n<article id=\"entry-dgp-24151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόσσαι, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3366 na letra κ · nº geral 24151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pedras salientes ou andaimes em forma de escada ao longo de uma construção.</p></section></article>\n<article id=\"entry-dgp-24152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κροσσαίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3367 na letra κ · nº geral 24152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o território de Crossa, região macedônica.</p></section></article>\n<article id=\"entry-dgp-24153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροσσός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3368 na letra κ · nº geral 24153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">franja; borda.</p></section></article>\n<article id=\"entry-dgp-24154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροσσωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3369 na letra κ · nº geral 24154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guarnecido de franja ou de borda. 〈κροσσός〉</p></section></article>\n<article id=\"entry-dgp-24155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροταλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3370 na letra κ · nº geral 24155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐκροτάλισα) 1 sacudir; fazer ressoar sacudindo 2 tocar castanholas 3 bater palmas; aplaudir. 〈κρόταλον〉</p></section></article>\n<article id=\"entry-dgp-24156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόταλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3371 na letra κ · nº geral 24156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 castanhola 2 narciso, flor ♦ adj. 3 que repete; tagarela (pessoa). 〈κρότος〉</p></section></article>\n<article id=\"entry-dgp-24157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρόταφος, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3372 na letra κ · nº geral 24157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ger. pl. têmporas 2 flanco da montanha 3 dorso (de rolo de papiro) 4 laterais (de peça).</p></section></article>\n<article id=\"entry-dgp-24158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3373 na letra κ · nº geral 24158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κροτήσω, aor. ἐκρότησα, perf. κεκρότηκα) 1 fazer ressoar: κείν’ ὄχεα κροτέοντες hom. [cavalos] fazendo ressoar os carros vazios 2 bater em; dar pancadas em algo ou alguém, ac.: κρ. λέβητας her. bater nos caldeirões, κρ. γῆν θύρσῳ eur. bater no solo com o tirso 3 bater em um instrumento, ac., para fazê-lo ressoar: κρ. χαλκώματα plut. fazer ressoar címbalos de bronze 4 fazer barulho: κρ. ὀστράκοις καὶ ψήφοις artt. fazer barulho com conchas e calhaus 5 bater com o martelo de ferreiro; forjar; martelar; malhar (um metal) 6 forjar; fabricar (discurso) 7 bater um contra o outro; fazer chocar-se: κρ. τὰς χεῖρας her. ou τὼ χεῖρε xen. bater as mãos 8 bater palmas; aplaudir 9 rar. bater as mãos em sinal de desaprovação. 〈κρότος〉</p></section></article>\n<article id=\"entry-dgp-24159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροτησμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3374 na letra κ · nº geral 24159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barulho de coisas que se entrechocam. 〈κροτέω〉</p></section></article>\n<article id=\"entry-dgp-24160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροτητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3375 na letra κ · nº geral 24160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ressonante 2 batido ♦ τὰ κροτητά 3 caminhos freqüentados, batidos 4 espécie de torta. 〈κροτέω〉</p></section></article>\n<article id=\"entry-dgp-24161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροτοθόρυβος, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3376 na letra κ · nº geral 24161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aplauso ruidoso. 〈κρότος, θόρυβος〉</p></section></article>\n<article id=\"entry-dgp-24162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρότος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3377 na letra κ · nº geral 24162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 som; barulho de percussão 2 barulho que se produz por meio de pancadas em algo, gen.: κρ. δακτύλων el. o estalar dos dedos, κρ. ποδῶν eur. o som dos pés na dança, κρ. χείρων aristd. o bater palmas, aplauso 3 som de discurso, de canto.</p></section></article>\n<article id=\"entry-dgp-24163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροτών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3378 na letra κ · nº geral 24163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rícino, arbusto que produz bagas de onde se extrai o óleo 2 óleo de rícino.</p></section></article>\n<article id=\"entry-dgp-24164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρότων, ωνος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3379 na letra κ · nº geral 24164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Crotona, cidade da Magna Grécia.</p></section></article>\n<article id=\"entry-dgp-24165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κροτωνιᾶται, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3380 na letra κ · nº geral 24165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os habitantes de Crotona; crotonienses. 〈Κρότων〉</p></section></article>\n<article id=\"entry-dgp-24166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κροτωνιᾶτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 3381 na letra κ · nº geral 24166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Crotona. 〈Κρότων〉</p></section></article>\n<article id=\"entry-dgp-24167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κροτωνιῆται, Κροτωνιῆτις</h1><div class=\"entry-meta\"><span>DGP · ordem 3382 na letra κ · nº geral 24167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Κροτωνιᾶται, Κροτω­νιᾶτις.</p></section></article>\n<article id=\"entry-dgp-24168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροῦμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3383 na letra κ · nº geral 24168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 golpe; toque 2 ação de tocar, com o plectro, um instrumento de cordas 3 som produzido por instrumento de cordas ao toque do plectro 4 ária ou trecho musical tocada em lira ou em harpa ou em instrumento de sopro. 〈κρούω〉</p></section></article>\n<article id=\"entry-dgp-24169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρουματικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3384 na letra κ · nº geral 24169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que concerne à ação de tocar com o plectro um instrumento: διάλεκτος κρουματική plut. o modo de tocar o plectro. 〈κροῦμα〉</p></section></article>\n<article id=\"entry-dgp-24170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρουνοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3385 na letra κ · nº geral 24170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">as Fontes, fonte e região da Élida. 〈κρουνός〉</p></section></article>\n<article id=\"entry-dgp-24171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρουνός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3386 na letra κ · nº geral 24171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fonte 2 jato (de sangue) 3 fluxo de palavras 4 corrente (de lava) 5 canal.</p></section></article>\n<article id=\"entry-dgp-24172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροῦσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3387 na letra κ · nº geral 24172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de bater, de chocar: ἡ πρὸς ἄλλη­λα κρ. τῶν ὅπλων plut. entrechoque das armas 2 ação de tocar um instrumento de cordas ou de sopro 3 ária musical: παρὰ τὴν κροῦσιν λέγειν plut. recitar ao som de música, παρὰ τὴν κροῦσιν ἄδειν plut. cantar com acompanhamento musical, κρ. ὑπὸ τὴν ᾠδήν plut. acompanhamento musical para o canto 4 capacidade de atingir, de ser incisivo ou de enganar 5 artifício retórico. 〈κρούω〉</p></section></article>\n<article id=\"entry-dgp-24173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρουσματικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3388 na letra κ · nº geral 24173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κρουματικός.</p></section></article>\n<article id=\"entry-dgp-24174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρουστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 3389 na letra κ · nº geral 24174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de κρούω.</p></section></article>\n<article id=\"entry-dgp-24175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρουστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3390 na letra κ · nº geral 24175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que bate; que choca 2 ressoante; vibrante 3 que emite a nota certa ♦ τὸ κρουστικόν 4 eloqüência expressiva. 〈κρούω〉</p></section></article>\n<article id=\"entry-dgp-24176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρούω</h1><div class=\"entry-meta\"><span>DGP · ordem 3391 na letra κ · nº geral 24176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κρούσω, aor. ἔκρουσα, perf. κέκρουκα; pas. aor. ἐκρούσθην, perf. κέκρουμαι) 1 bater; dar pancada em, ac.: κρ. τὴν θύραν ar. bater à porta, εἱλικτὸν κρούσω πόδ’ ἐμόν eur. baterei o pé em cadência (na dança) 2 bater um contra o outro: κρ. ὅπλα πρὸς ἄλληλα tuc. bater as armas umas contra as outras, κρ. τὰς ἀσπίδας πρὸς τὰ δόρατα xen. fazer chocar os escudos contra as lanças, κρ. χεῖρας eur. aplaudir 3 tocar com o plectro as cordas de instrumento; tocar instrumento de cordas 4 tocar instrumento musical de corda ou de sopro 5 golpear ou empurrar para pôr em movimento 6 bater num copo, ac., com os dedos para fazê-lo ressoar 7 pôr à prova, ac.: κρ. τὸν κόλακα plut. pôr à prova o adulador ♦ at. e méd. 8 Náut. remar: κρούω ou κρούεσθαι πρύμναν remar para trás.</p></section></article>\n<article id=\"entry-dgp-24177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύβδα</h1><div class=\"entry-meta\"><span>DGP · ordem 3392 na letra κ · nº geral 24177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. secretamente; em segredo; às ocultas de alguém, gen. 〈κρύπτω〉</p></section></article>\n<article id=\"entry-dgp-24178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύβδην</h1><div class=\"entry-meta\"><span>DGP · ordem 3393 na letra κ · nº geral 24178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = κρύβδα.</p></section></article>\n<article id=\"entry-dgp-24179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυβῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 3394 na letra κ · nº geral 24179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 pas. de κρύπτω.</p></section></article>\n<article id=\"entry-dgp-24180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύβω</h1><div class=\"entry-meta\"><span>DGP · ordem 3395 na letra κ · nº geral 24180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = κρύπτω.</p></section></article>\n<article id=\"entry-dgp-24181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3396 na letra κ · nº geral 24181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 frio; gelado 2 que faz gelar de medo; apa­vorante; terrível. 〈κρύος〉</p></section></article>\n<article id=\"entry-dgp-24182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3397 na letra κ · nº geral 24182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 frio 2 a estação de frio; inverno 3 Medic. calafrio (de febre). 〈κρύος〉</p></section></article>\n<article id=\"entry-dgp-24183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 3398 na letra κ · nº geral 24183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 glacial 2 que gela de medo. 〈κρυός〉</p></section></article>\n<article id=\"entry-dgp-24184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3399 na letra κ · nº geral 24184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 frio glacial; frio 2 calafrio de medo.</p></section></article>\n<article id=\"entry-dgp-24185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύπτασκε</h1><div class=\"entry-meta\"><span>DGP · ordem 3400 na letra κ · nº geral 24185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de κρύπτω.</p></section></article>\n<article id=\"entry-dgp-24186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυπτεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3401 na letra κ · nº geral 24186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de emboscada que os jovens espartanos armavam aos hilotas. 〈κρύπτω〉</p></section></article>\n<article id=\"entry-dgp-24187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυπτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 3402 na letra κ · nº geral 24187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de κρύπτω.</p></section></article>\n<article id=\"entry-dgp-24188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυπτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 3403 na letra κ · nº geral 24188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esconder 2 intr. ocultar-se em emboscada; esconder-se ♦ pas. 3 estar exposto a emboscada; ser alvo de emboscada. 〈κρύπτω〉</p></section></article>\n<article id=\"entry-dgp-24189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύπτη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3404 na letra κ · nº geral 24189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. lugar subterrâneo; cripta. 〈κρυπτός〉</p></section></article>\n<article id=\"entry-dgp-24190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3405 na letra κ · nº geral 24190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 oculto; secreto 2 encoberto; protegido de, gen. 3 obscuro; ininteligível 4 dissimulado; enganoso. 〈κρύπτω〉</p></section></article>\n<article id=\"entry-dgp-24191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 3406 na letra κ · nº geral 24191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κρύψω, aor. ἔκρυψα, perf. desus.; pas. fut. κρυ­φθήσομαι, aor. ἐκρύφθην, perf. κέκρυμμαι) 1 cobrir; esconder; cobrir para proteger; pôr algo ou alguém, ac., ao abrigo de, dat. ou ὑπό e dat.: κρ. κεφαλὰς κορύθεσσιν hom. cobrir suas cabeças com capacetes 2 esconder para resguardar dos olhares: κρ. ἑαυτόν sóf. esconder-se, σύ μ’ ἐξ ὁδοῦ πόδα κρύψον κατ’ ἄλσος sóf. guia meus pés fora do caminho e esconde-me no bosque sagrado 3 pôr debaixo de, dat. ou κατά e gen.: κρ. γῇ her., κατὰ γῆς plut. despositar sob a terra, κρ. τάφῳ sóf. depositar no túmulo 4 fazer mistério de algo, ac.; ocultar algo, ac., de alguém, ac. ou πρός e ac. 5 guardar consigo; não revelar; não expor: τί κρύψει; sóf. o que ele guardará consigo? ou o que ele não revelará? 6 intr. ocultar-se; ficar escondido ♦ méd. 7 esconder para si ou em si: κρ. κάρα sóf. esconder sua cabeça 8 esconder; ocultar; calar: κρ. τἀληθές sóf. calar a verdade 9 intr. esconder-se; desaparecer 10 part. perf. κεκρυμμένος guardado; oculto.</p></section></article>\n<article id=\"entry-dgp-24192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυσταλλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3407 na letra κ · nº geral 24192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. ser brilhante ou transparente como o cristal. 〈κρύσταλλος〉</p></section></article>\n<article id=\"entry-dgp-24193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυσταλλοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3408 na letra κ · nº geral 24193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante ao gelo ou ao cristal. 〈κρύσταλλος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-24194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυσταλλοειδῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 3409 na letra κ · nº geral 24194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. como cristal.</p></section></article>\n<article id=\"entry-dgp-24195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυσταλλοπήξ, -πῆγος</h1><div class=\"entry-meta\"><span>DGP · ordem 3410 na letra κ · nº geral 24195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que se transformou em gelo; congelado. 〈κρύσταλλος, πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-24196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύσταλλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3411 na letra κ · nº geral 24196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 água congelada; gelo 2 frio glacial 3 torpor 4 vidro transparente; cristal.</p></section></article>\n<article id=\"entry-dgp-24197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύφα</h1><div class=\"entry-meta\"><span>DGP · ordem 3412 na letra κ · nº geral 24197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. secretamente; em segredo; às ocultas de alguém, gen. 〈κρύπτω〉</p></section></article>\n<article id=\"entry-dgp-24198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυφαῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 3413 na letra κ · nº geral 24198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 oculto 2 clandestino; secreto. 〈κρύφα〉</p></section></article>\n<article id=\"entry-dgp-24199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυφαίως</h1><div class=\"entry-meta\"><span>DGP · ordem 3414 na letra κ · nº geral 24199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. às ocultas; em segredo.</p></section></article>\n<article id=\"entry-dgp-24200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυφείς</h1><div class=\"entry-meta\"><span>DGP · ordem 3415 na letra κ · nº geral 24200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. de κρύπτω.</p></section></article>\n";
